<script setup lang="ts">
import { Link } from '@inertiajs/vue3'; import { ref,onMounted,onBeforeUnmount } from 'vue'; import BaseLayout from '../../layouts/BaseLayout.vue'; import HostNav from '../../components/hote/HostNav.vue';import HostNotificationCard,{type HostNotice} from '../../components/hote/HostNotificationCard.vue';import { usePolling } from '../../pilotage/usePolling';
defineProps<{ linked: boolean; unread: number; items: { data: HostNotice[]; prev_page_url: string|null; next_page_url: string|null } }>();usePolling(['items','unread'],2500);
const online=ref(navigator.onLine);const changed=()=>{online.value=navigator.onLine;};onMounted(()=>{window.addEventListener('online',changed);window.addEventListener('offline',changed);});onBeforeUnmount(()=>{window.removeEventListener('online',changed);window.removeEventListener('offline',changed);});
</script>
<template><BaseLayout><HostNav /><h1 class="mb-4 text-display font-bold">Mes notifications</h1><p v-if="!online" role="alert" class="mb-4 rounded border-2 border-ikoma-orange p-4">⚠ Sans réseau : reconnectez-vous pour recevoir les nouvelles demandes.</p><p v-if="!linked" class="rounded-xl border-2 p-5">Aucune fiche hôte n’est rattachée à votre compte. Contactez l’administrateur.</p><template v-else><p class="mb-6 font-semibold" data-testid="notifications-non-lues">{{ unread }} notification(s) non lue(s)</p><div class="space-y-5"><HostNotificationCard v-for="item in items.data" :key="item.id" :notice="item" /></div><p v-if="!items.data.length">Aucune notification pour le moment.</p><nav class="mt-6 flex gap-3" aria-label="Pages des notifications"><Link v-if="items.prev_page_url" class="btn-soft" :href="items.prev_page_url">Précédentes</Link><Link v-if="items.next_page_url" class="btn-soft" :href="items.next_page_url">Suivantes</Link></nav></template></BaseLayout></template>
